set lock_timeout = '5s';
set client_min_messages = warning;

do $l22$ begin
  if to_regclass('public.character_facts') is null or to_regclass('public.entity_sources') is null then
    raise exception 'L22: 023 and L13 must be applied first';
  end if;
  if (select count(*) from public.character_facts) < 750 then
    raise exception 'L22: the 750 character_facts rows of L13 are not all there (apply L13 first)';
  end if;
end $l22$;

-- Precheck of the next 7 days (AUDITS-COMMON): haise-sasaki stop being a possible answer of otakudle, so none of them may be today's answer or scheduled in the next 7 days; otherwise the file aborts and is applied after that day.
do $l22$
declare r record;
begin
  if to_regclass('public.dle_schedule') is not null and to_regclass('public.dle_games') is not null then
    for r in
      select g.id as game_id, c.slug, s.bank_day
      from public.dle_games g
      join public.dle_schedule s on s.game_id = g.id
      join public.characters c on c.id::text = s.entity_id
      join public.groups gr on gr.id = c.group_id and gr.site_id = 'anime'
      where g.id = 'otakudle' and g.epoch is not null and (gr.slug, c.slug) in (('tokyo-ghoul', 'haise-sasaki'))
        and s.bank_day in (select public.dle_bank_day(g.epoch, public.dle_utc_date(now()) + k) from generate_series(0, 7) as k)
      union all
      select g.id, c.slug, null from public.dle_games g join public.dle_daily_stats d on d.game_id = g.id and d.play_date >= public.dle_utc_date(now())
      join public.characters c on c.id::text = d.entity_id join public.groups gr on gr.id = c.group_id and gr.site_id = 'anime'
      where g.id = 'otakudle' and (gr.slug, c.slug) in (('tokyo-ghoul', 'haise-sasaki'))
    loop
      raise exception 'L22: % is the answer of % (bank day %) today or in the next 7 days: apply this file after that day', r.slug, r.game_id, coalesce(r.bank_day::text, 'served today');
    end loop;
  end if;
end $l22$;

create temp table l22_fix (id text primary key, series text, slug text, col text, old_v text, new_v text) on commit drop;
create temp table l22_src (id text, op text, entity_id text, field text, source text, ref text, url text, fetched text) on commit drop;
create temp table l22_new (series text, slug text, gender text, species text, role_at_debut text, first_appearance text, voice_actor_ja text, featured boolean) on commit drop;

do $l22$
declare
  c record; s record; n record; cid bigint; cur text;
  n_changed integer := 0; n_already integer := 0; n_drift integer := 0; n_missing integer := 0; n_new integer := 0;
begin
  for c in select * from l22_fix order by id loop
    select ch.id into cid from public.characters ch join public.groups g on g.id = ch.group_id and g.site_id = 'anime' and g.slug = c.series
      join public.character_facts f on f.character_id = ch.id where ch.slug = c.slug;
    if cid is null then
      n_missing := n_missing + 1;
      raise warning 'L22 %: no facts row for % / %', c.id, c.series, c.slug;
      continue;
    end if;
    execute format('select %I::text from public.character_facts where character_id = $1', c.col) into cur using cid;
    if cur is not distinct from c.old_v then
      execute format('update public.character_facts set %I = $2::%s where character_id = $1', c.col, case when c.col = 'featured' then 'boolean' else 'text' end) using cid, c.new_v;
      n_changed := n_changed + 1;
    elsif cur is not distinct from c.new_v then
      n_already := n_already + 1;
    else
      n_drift := n_drift + 1;
      raise warning 'L22 %: % / % holds %, neither % nor %: left alone', c.id, c.series, c.slug, cur, c.old_v, c.new_v;
      continue;
    end if;
    for s in select * from l22_src w where w.id = c.id loop
      if s.op = 'delete' then
        delete from public.entity_sources where entity_type = 'character' and entity_id = s.entity_id and field = s.field and source = s.source;
      else
        on conflict (entity_type, entity_id, field, source) do update set source_ref = excluded.source_ref, source_url = excluded.source_url, fetched_at = excluded.fetched_at
        where (entity_sources.source_ref, entity_sources.source_url, entity_sources.fetched_at) is distinct from (excluded.source_ref, excluded.source_url, excluded.fetched_at);
      end if;
    end loop;
  end loop;
  -- the sources of values that stay (OT-D4: a role that had no external source) and of the new rows: upserted or deleted by key
  for s in select * from l22_src w where not exists (select 1 from l22_fix f where f.id = w.id) order by id, field, source loop
    if s.op = 'delete' then
      delete from public.entity_sources where entity_type = 'character' and entity_id = s.entity_id and field = s.field and source = s.source;
    else
      on conflict (entity_type, entity_id, field, source) do update set source_ref = excluded.source_ref, source_url = excluded.source_url, fetched_at = excluded.fetched_at
      where (entity_sources.source_ref, entity_sources.source_url, entity_sources.fetched_at) is distinct from (excluded.source_ref, excluded.source_url, excluded.fetched_at);
    end if;
  end loop;
  -- a character that had no facts row (Ken Kaneki): inserted
  for n in select * from l22_new loop
    select ch.id into cid from public.characters ch join public.groups g on g.id = ch.group_id and g.site_id = 'anime' and g.slug = n.series where ch.slug = n.slug;
    if cid is null then
      raise exception 'L22: character %/% is missing (apply L04 first)', n.series, n.slug;
    end if;
    if found then n_new := n_new + 1; end if;
  end loop;
  if n_missing > 0 then
    raise exception 'L22: % corrections found no row (apply L13 first)', n_missing;
  end if;
  if n_drift = 0 and n_changed not in (0, 134) then
    raise exception 'L22: % rows changed, expected 0 or 134', n_changed;
  end if;
  if n_new not in (0, 1) then
    raise exception 'L22: % new rows, expected 0 or 1', n_new;
  end if;
  raise notice 'L22: % changed, % already as wanted, % left alone, % new rows', n_changed, n_already, n_drift, n_new;
end $l22$;

-- OT-D1: hisoka-morrow is the same person as hisoka-morow (the featured one). Excluded from the pool by the curation table; a row already there is left alone.
do $l22$
declare cid bigint;
begin
  if to_regclass('public.dle_curation') is null or not exists (select 1 from public.dle_games where id = 'otakudle') then
    raise notice 'L22: no dle_curation or no game otakudle: the Hisoka curation is skipped';
    return;
  end if;
  select ch.id into cid from public.characters ch join public.groups g on g.id = ch.group_id and g.site_id = 'anime' and g.slug = 'hunter-x-hunter' where ch.slug = 'hisoka-morrow';
  if cid is null then raise exception 'L22: hisoka-morrow is missing'; end if;
end $l22$;

-- The snapshot the players read (a game that has none is refreshed by its own activation).
do $l22$ begin
  if exists (select 1 from public.dle_entities where game_id = 'otakudle') then perform public.dle_refresh_entities('otakudle'); end if;
end $l22$;

-- Nobody scheduled in the next 7 days may have stopped being a possible answer.
do $l22$
declare r record;
begin
  if to_regclass('public.dle_schedule') is not null and to_regclass('public.dle_games') is not null and to_regclass('public.dle_entities') is not null then
    for r in
      select s.game_id, s.entity_id, s.bank_day from public.dle_games g join public.dle_schedule s on s.game_id = g.id
      join public.dle_entities e on e.game_id = s.game_id and e.entity_id = s.entity_id
      where g.id = 'otakudle' and g.epoch is not null and not (e.can_be_target and e.in_pool)
        and s.bank_day in (select public.dle_bank_day(g.epoch, public.dle_utc_date(now()) + k) from generate_series(0, 7) as k)
    loop
      raise exception 'L22: entity % of % (bank day %) is scheduled in the next 7 days and is no longer a possible answer', r.entity_id, r.game_id, r.bank_day;
    end loop;
    if to_regclass('public.dle_daily_stats') is not null and exists (select 1 from public.dle_daily_stats d join public.dle_entities e on e.game_id = d.game_id and e.entity_id = d.entity_id
       where d.game_id = 'otakudle' and d.play_date >= public.dle_utc_date(now()) and not (e.can_be_target and e.in_pool)) then
      raise exception 'L22: the answer served today is no longer a possible answer';
    end if;
  end if;
end $l22$;

notify pgrst, 'reload schema';
